/** Cards and their masteries. */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    build
 * depends    scripts/game-wiki/render.mjs
 * used by    —
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
import { heading, infobox, sections, table, titleCase } from '../render.mjs'

export function build(context) {
  const { data } = context.sdk
  const { format } = context
  const cards = data.CARD_TEMPLATES

  /** A card value in the form its `levelType` says it takes. */
  const shown = (type, value) => {
    if (type === 'multi') return `x${format.value(value)}`
    if (type === 'percent') return `${format.value(value)}%`
    return format.value(value)
  }

  for (const card of cards) {
    context.page(
      `Card: ${card.name}`,
      sections(
        card.description,
        infobox([
          ['Rarity', titleCase(card.rarity)],
          ['Draw chance for this rarity', format.percent(data.RARITY_CHANCES[card.rarity])],
          ['Maximum copies', data.CARD_MAX_COPIES],
        ]),
        heading(2, 'Levels'),
        table(['Level', 'Value'], card.levelValues.map((value, index) => [data.CARD_LEVELS[index], shown(card.levelType, value)])),
        heading(2, `Mastery: ${card.masteryName}`),
        card.masteryDescription,
        table(
          ['Mastery level', 'Value'],
          card.masteryValues.map((value, index) => [data.CARD_MASTERY_EFFECT_LEVELS[index], shown(card.masteryType, value)]),
        ),
        `Back to ${context.link('Cards')}.`,
      ),
      { source: 'CARD_TEMPLATES' },
    )
  }

  const rarities = Object.keys(data.RARITY_CHANCES)
  context.page(
    'Cards',
    sections(
      context.overview('cards'),
      heading(2, 'Draw Chances'),
      table(['Rarity', 'Chance', 'Cards'], rarities.map(rarity => [
        titleCase(rarity),
        format.percent(data.RARITY_CHANCES[rarity]),
        cards.filter(card => card.rarity === rarity).length,
      ])),
      ...rarities.map(rarity =>
        sections(
          heading(2, `${titleCase(rarity)} Cards`),
          table(
            ['Card', 'Effect', 'Level 1', `Level ${data.CARD_LEVELS.at(-1)}`, 'Mastery'],
            cards
              .filter(card => card.rarity === rarity)
              .map(card => [
                context.link(`Card: ${card.name}`, card.name),
                card.description,
                shown(card.levelType, card.levelValues[0]),
                shown(card.levelType, card.levelValues.at(-1)),
                card.masteryName,
              ]),
          ),
        ),
      ),
    ),
    { source: ['CARD_TEMPLATES', 'RARITY_CHANCES'] },
  )

  context.group('Cards', ['Cards'])
}
